import { TaskAlreadyDoneError } from "../domain/errors";
import { TaskRepository } from "../domain/task-repository";
import { ApplicationError } from "./application-error";
import { TaskOutput } from "./dtos";

export class MarkTaskDoneUseCase {
  public constructor(private readonly tasks: TaskRepository) {}

  public async execute(taskId: string): Promise<TaskOutput> {
    const task = await this.tasks.findById(taskId);
    if (!task) throw new ApplicationError("task not found", 404);
    try { task.markDone(); } catch (error) {
      if (error instanceof TaskAlreadyDoneError) throw new ApplicationError(error.message, 409);
      throw error;
    }
    await this.tasks.save(task);
    return { id: task.id, projectId: task.projectId, title: task.title, description: task.description, dueDate: task.dueDate?.toISOString(), assigneeId: task.assigneeId, status: task.getStatus() };
  }
}

